import boto3

def embed_transcript_segments(text_segments):
    comprehend = boto3.client('comprehend')
    embeddings = []
    for segment in text_segments:
        response = comprehend.detect_dominant_language(Text=segment)
        if response['Languages'][0]['LanguageCode'] == 'en':
            embed_response = comprehend.detect_sentiment(Text=segment, LanguageCode='en')
            embeddings.append(embed_response['SentimentScore'])
    return embeddings

import boto3

def moderate_transcript(transcript_text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_toxic_content(
        TextSegments=[
            {
                'Text': transcript_text
            }
        ],
        LanguageCode='en'
    )
    if response['ResultList'][0]['Toxicity']['Label'] == 'TOXIC':
        return 'Moderation failed: Unsafe content detected'
    else:
        return 'Moderation passed: Safe content'

from google.cloud import speech_v1 as speech

class SpeechRequest:
    def __init__(self, audio_content):
        self.audio_content = audio_content

    def to_dict(self):
        return {
            'config': {
                'encoding': 'LINEAR16',
                'sample_rate_hertz': 16000,
                'language_code': 'en-US',
            },
            'audio': {
                'content': self.audio_content,
            }
        }

class SpeechResponse:
    def __init__(self, response):
        self.response = response

    def to_text(self):
        return ' '.join([result.alternatives[0].transcript for result in self.response.results])

def normalize_transcript(transcript):
    return transcript.lower().strip()

from google.cloud import speech

def get_timestamped_transcript(transcription_result):
    client = speech.SpeechClient()
    response = client.recognize(transcription_result)
    for result in response.results:
        for alternative in result.alternatives:
            words = alternative.words
            for word_info in words:
                start_time = word_info.start_time
                end_time = word_info.end_time
                word = word_info.word
                print(f"Word: {word}, Start Time: {start_time}, End Time: {end_time}")

